341	// validMonth 严格校验 YYYY-MM（月份两位、01..12）。
342	func validMonth(m string) bool {
343		t, err := time.Parse("2006-01", m)
344		if err != nil || t.Format("2006-01") != m || t.Year() < 1 {
345			return false
346		}
347		return true
348	}
349	
350	// inMonth 判定一条 RFC3339 时间（换算 UTC 后）是否落在给定自然月。
351	func inMonth(rfc3339, month string) bool {
352		t, err := time.Parse(time.RFC3339, rfc3339)
353		if err != nil {
354			return false
355		}
356		return t.UTC().Format("2006-01") == month
357	}
