458	func sortByInstant(us []*usageRecord) {
459		// 入参时间均已在载入/导入时校验为 RFC3339。
460		sort.Slice(us, func(i, j int) bool {
461			ti, _ := time.Parse(time.RFC3339, us[i].Time)
462			tj, _ := time.Parse(time.RFC3339, us[j].Time)
463			ui, uj := ti.UTC(), tj.UTC()
464			if !ui.Equal(uj) {
465				return ui.Before(uj)
466			}
467			return us[i].ID < us[j].ID
468		})
469	}
