477	func printBill(b *bill, cust *customer, adjs []*adjustment, pays []*payment) {
478		fmt.Fprintf(stdout, "账单标识：%s\n", b.ID)
479		fmt.Fprintf(stdout, "客户：%s（%s）\n", cust.ID, cust.Name)
480		fmt.Fprintf(stdout, "月份：%s（UTC 自然月，左闭右开）\n", b.Month)
481		fmt.Fprintf(stdout, "单价：%d 分（%s）\n", b.UnitPrice, moneyFen(b.UnitPrice))
482		fmt.Fprintf(stdout, "总数量：%d\n", b.TotalQty)
483		fmt.Fprintf(stdout, "总金额：%d 分（%s）\n", b.TotalFee, moneyFen(b.TotalFee))
484		// 数据在载入时已校验一致，此处计算不会出错。
485		net, payable, _ := billTotals(b, adjs)
486		received, _ := paymentReceived(pays, b.Month)
487		outstanding := payable - received // 不变量保证 0 ≤ 实收 ≤ 当前应付
488		fmt.Fprintf(stdout, "调整净额：%+d 分（%s）\n", net, moneyFen(net))
489		fmt.Fprintf(stdout, "当前应付：%d 分（%s）\n", payable, moneyFen(payable))
490		fmt.Fprintf(stdout, "实收：%d 分（%s）\n", received, moneyFen(received))
491		fmt.Fprintf(stdout, "未收余额：%d 分（%s）\n", outstanding, moneyFen(outstanding))
492		fmt.Fprintln(stdout, "明细：")
493		for i, ln := range b.Lines {
494			fmt.Fprintf(stdout, "  %d. 用量标识=%s 时间=%s 数量=%d 小计=%d 分（%s）\n",
495				i+1, ln.UsageID, ln.Time, ln.Quantity, ln.LineFee, moneyFen(ln.LineFee))
496		}
497		if len(adjs) == 0 {
498			fmt.Fprintln(stdout, "调整与撤销历史：无")
499		} else {
500			fmt.Fprintln(stdout, "调整与撤销历史（按成功操作顺序）：")
501			for i, ev := range historyEvents(adjs) {
502				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
503			}
504		}
505		if len(pays) == 0 {
506			fmt.Fprintln(stdout, "收款与撤销历史：无")
507		} else {
508			fmt.Fprintln(stdout, "收款与撤销历史（按成功操作顺序）：")
509			for i, ev := range paymentHistoryEvents(pays, b.Month) {
510				fmt.Fprintf(stdout, "  %d. %s\n", i+1, ev)
511			}
512		}
513	}
