515	// historyEvents 把调整与撤销展开为按操作序号排序的可读历史条目。
516	func historyEvents(adjs []*adjustment) []string {
517		type event struct {
518			seq  int64
519			text string
520		}
521		var events []event
522		for _, a := range adjs {
523			events = append(events, event{a.Seq, fmt.Sprintf("调整 %s：%s %+d 分（%s），原因：%s，当前状态：%s",
524				a.ID, adjustKind(a.Amount), a.Amount, moneyFen(a.Amount), a.Reason, adjustStatus(a))})
525			if a.Revoked {
526				events = append(events, event{a.RevokeSeq, fmt.Sprintf("撤销 %s：原因：%s（关联调整 %s 的%s %+d 分）",
527					a.ID, a.RevokeReason, a.ID, adjustKind(a.Amount), a.Amount)})
528			}
529		}
530		sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })
531		out := make([]string, len(events))
532		for i, ev := range events {
533			out[i] = ev.text
534		}
535		return out
536	}
