584	// parseAmount 解析调整金额：有符号 64 位整数、非零（正数补收、负数减免）。
585	func parseAmount(text string) (int64, error) {
586		text = strings.TrimSpace(text)
587		amount, err := strconv.ParseInt(text, 10, 64)
588		if err != nil {
589			return 0, fmt.Errorf("调整金额 %q 不是有符号 64 位整数范围内的整数: %w", text, err)
590		}
591		if amount == 0 {
592			return 0, fmt.Errorf("调整金额不能为零分（正数补收、负数减免）")
593		}
594		return amount, nil
595	}
