```go
func billLedger(s *state, b *bill) ([]ledgerEvent, error) {
	var events []ledgerEvent
	for _, a := range s.Adjustments {
		if a.CustomerID != b.CustomerID || a.Month != b.Month {
			continue
		}
		events = append(events, ledgerEvent{
			seq: a.Seq, kind: "调整", refID: a.ID,
			deltaPayable: a.Amount, note: a.Reason,
		})
		if a.Revoked {
			neg, err := neg64(a.Amount)
			if err != nil {
				return nil, fmt.Errorf("调整 %q 的金额无法抵消（越界）", a.ID)
			}
			events = append(events, ledgerEvent{
				seq: a.RevokeSeq, kind: "撤销调整", refID: a.ID,
				deltaPayable: neg, note: a.RevokeReason, linkSeq: a.Seq,
			})
		}
	}
	for _, p := range s.Payments {
		if p.CustomerID != b.CustomerID {
			continue
		}
		alloc := p.amountFor(b.Month)
		if alloc <= 0 {
			continue
		}
		events = append(events, ledgerEvent{
			seq: p.Seq, kind: "收款", refID: p.ID,
			deltaReceived: alloc, note: p.Note,
			isPayment: true, payTotal: p.Total, payAlloc: alloc,
		})
		if p.Revoked {
			events = append(events, ledgerEvent{
				seq: p.RevokeSeq, kind: "撤销收款", refID: p.ID,
				deltaReceived: -alloc, note: p.RevokeReason, linkSeq: p.Seq,
				isPayment: true, payTotal: p.Total, payAlloc: alloc,
			})
		}
	}
	sort.Slice(events, func(i, j int) bool { return events[i].seq < events[j].seq })

	// 核验完整流水（不受查询截止序号限制）：序号不得重复、撤销不得先于
	// 原操作，且每个事件之后都必须满足 0 ≤ 实收 ≤ 应付 ≤ 有符号 64 位
	// 最大值——只检查最终余额会放过中间越界的异常存档。
	payable := b.TotalFee
	var received int64
	seen := make(map[int64]string, len(events))
	for i := range events {
		ev := &events[i]
		if prev, dup := seen[ev.seq]; dup {
			return nil, fmt.Errorf("流水序号 %d 重复（%s 与 %s），数据异常", ev.seq, prev, ev.kind+" "+ev.refID)
		}
		seen[ev.seq] = ev.kind + " " + ev.refID
		if ev.linkSeq != 0 && ev.linkSeq >= ev.seq {
			return nil, fmt.Errorf("%s %q 的撤销序号 %d 不晚于原操作序号 %d，数据异常", ...)
		}
		var err error
		payable, err = addSigned64(payable, ev.deltaPayable)
		if err != nil {
			return nil, fmt.Errorf("序号 %d（%s %s）之后应付越出有符号 64 位范围，数据异常", ...)
		}
		received, err = addSigned64(received, ev.deltaReceived)
		if err != nil { ... 实收越界 ... }
		if payable < 0 {
			return nil, fmt.Errorf("序号 %d（%s %s）之后应付为 %d 分（小于 0），数据异常", ...)
		}
		if received < 0 { ... }
		if received > payable { ... }
		ev.afterPayable = payable
		ev.afterReceived = received
	}
	return events, nil
}
```

