```go
func formatLedgerEvent(ev ledgerEvent) string {
	impact := func(delta int64) string {
		return fmt.Sprintf("%+d 分（%s）", delta, moneyFen(delta))
	}
	after := fmt.Sprintf("事后：应付 %d 分，实收 %d 分，未收余额 %d 分",
		ev.afterPayable, ev.afterReceived, ev.afterPayable-ev.afterReceived)
	switch ev.kind {
	case "调整":
		return fmt.Sprintf("序号 %d 调整 %s：应付 %s（%s），原因：%s → %s",
			ev.seq, ev.refID, impact(ev.deltaPayable), adjustKind(ev.deltaPayable), ev.note, after)
	case "撤销调整":
		return fmt.Sprintf("序号 %d 撤销调整 %s：应付 %s（关联序号 %d 的调整 %s），原因：%s → %s",
			ev.seq, ev.refID, impact(ev.deltaPayable), ev.linkSeq, ev.refID, ev.note, after)
	case "收款":
		return fmt.Sprintf("序号 %d 收款 %s：实收 %s（汇款总额 %d 分，本账单分配 %d 分），备注：%s → %s",
			ev.seq, ev.refID, impact(ev.deltaReceived), ev.payTotal, ev.payAlloc, ev.note, after)
	default: // 撤销收款
		return fmt.Sprintf("序号 %d 撤销收款 %s：实收 %s（关联序号 %d 的收款 %s，汇款总额 %d 分，取消本账单分配 %d 分），原因：%s → %s",
			ev.seq, ev.refID, impact(ev.deltaReceived), ev.linkSeq, ev.refID, ev.payTotal, ev.payAlloc, ev.note, after)
	}
}
```

